cd /tmp/sv-45c4a6acdf8e457a85e8c493aff69994 && \
# Try to symbolicate libSystem.Native.so using the stripped binary's dynsym
python3 -c "
import subprocess

result = subprocess.run(['aarch64-linux-gnu-nm', '-D', '--defined-only', 'libSystem.Native.so.dbg'], 
                      capture_output=True, text=True)
if result.returncode != 0 or not result.stdout.strip():
    print('No symbols available for libSystem.Native.so (file may be invalid)')
else:
    symbols = []
    for line in result.stdout.splitlines():
        parts = line.split()
        if len(parts) >= 3 and parts[1] in ('T', 't', 'W', 'w'):
            symbols.append((int(parts[0], 16), parts[2]))
    symbols.sort()
    for t in [0x8f14, 0x12a48]:
        lo, hi = 0, len(symbols)-1
        best = None
        while lo <= hi:
            mid = (lo+hi)//2
            if symbols[mid][0] <= t:
                best = mid
                lo = mid+1
            else:
                hi = mid-1
        if best is not None:
            addr, name = symbols[best]
            print(f'0x{t:x} -> {name}+0x{t-addr:x}')
        else:
            print(f'0x{t:x} -> ???')
" 2>&1

